import { useState, useEffect } from 'react'
import Scene from './components/Scene'

function App() {
    const [loading, setLoading] = useState(true)
    const [progress, setProgress] = useState(0)
    const [showDialog, setShowDialog] = useState(false)
    const [animationStarted, setAnimationStarted] = useState(false)
    const [showBadMessage, setShowBadMessage] = useState(false)
    const [, setShowReturnButton] = useState(false)
    const [isAnimationFinished, setIsAnimationFinished] = useState(false)

    useEffect(() => {
        // Simulate loading progress
        const interval = setInterval(() => {
            setProgress(prev => {
                if (prev >= 100) {
                    clearInterval(interval)
                    setTimeout(() => {
                        setLoading(false)
                        setShowDialog(true)
                    }, 300)
                    return 100
                }
                return prev + 10
            })
        }, 200)

        return () => clearInterval(interval)
    }, [])

    const handleYes = () => {
        setShowDialog(false)
        setAnimationStarted(true)
        setShowReturnButton(false)
    }

    const handleNo = () => {
        setShowDialog(false)
        setShowBadMessage(true)
    }

    const handleReturn = () => {
        setShowBadMessage(false)
        setAnimationStarted(false)
        setShowReturnButton(false)
        setShowDialog(true)
    }

    const handleAnimationComplete = () => {
        // Hide title in FINISHED phase
        setIsAnimationFinished(true)
        // Show return button after a short delay
        setTimeout(() => {
            setShowReturnButton(true)
        }, 1000)
    }

    return (
        <>
            {/* Loading Screen */}
            {loading && (
                <div className={`loading-screen ${progress === 100 ? 'fade-out' : ''}`}>
                    <div className="loading-content">
                        <h1 className="loading-title">🎄 Danniya 的圣诞狂欢 🎄</h1>
                        <p className="loading-subtitle">正在加载魔法体验...</p>
                        <div className="loading-bar">
                            <div
                                className="loading-progress"
                                style={{ width: `${progress}%` }}
                            />
                        </div>
                    </div>
                </div>
            )}

            {/* Start Dialog */}
            {showDialog && (
                <div className="dialog-overlay">
                    <div className="dialog-box">
                        <h2 className="dialog-title">开始 Danniya 的圣诞狂欢？</h2>
                        <div className="dialog-buttons">
                            <button className="dialog-btn yes-btn" onClick={handleYes}>
                                YES
                            </button>
                            <button className="dialog-btn no-btn" onClick={handleNo}>
                                NO
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Bad Message with Return Button */}
            {showBadMessage && (
                <div className="bad-message-overlay">
                    <h1 className="bad-message">You bad bad</h1>
                    <button className="return-btn" onClick={handleReturn}>
                        返回
                    </button>
                </div>
            )}

            {/* Main 3D Scene - Only render after YES is clicked */}
            {animationStarted && (
                <div style={{
                    position: 'fixed',
                    top: 0,
                    left: 0,
                    width: '100%',
                    height: '100%',
                    zIndex: 1
                }}>
                    <Scene isActive={animationStarted} onAnimationComplete={handleAnimationComplete} />
                </div>
            )}

            {/* UI Overlay - Title hidden in FINISHED phase */}
            {!isAnimationFinished && (
                <div className="ui-overlay">
                    <div className="title-container">
                        <h1 className="main-title">Danniya 的圣诞狂欢</h1>
                    </div>
                </div>
            )}
        </>
    )
}

export default App
