import { useRef, useMemo, useState } from 'react'
import { useFrame, useLoader } from '@react-three/fiber'
import { Points, PointMaterial, Text } from '@react-three/drei'
import * as THREE from 'three'
import usagiImg from '../assets/usagi.png'

// Animation phases
enum AnimationPhase {
    FORMING_TREE = 0,
    TREE_DISPLAY = 1,
    FORMING_TEXT = 2,
    TEXT_DISPLAY = 3,
    FINISHED = 4
}

// Phase durations in seconds
const PHASE_DURATIONS = {
    [AnimationPhase.FORMING_TREE]: 5,
    [AnimationPhase.TREE_DISPLAY]: 3,
    [AnimationPhase.FORMING_TEXT]: 4,
    [AnimationPhase.TEXT_DISPLAY]: 0.1, // Skip this phase quickly
    [AnimationPhase.FINISHED]: Infinity
}

// Easing functions
const easeInOutCubic = (t: number) =>
    t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2

interface ParticleAnimationProps {
    isActive: boolean
    onAnimationComplete?: () => void
}

export default function ParticleAnimation({ isActive }: ParticleAnimationProps) {
    const textRef = useRef<THREE.Mesh>(null)
    const pointsRef = useRef<THREE.Points>(null)
    const glowPointsRef = useRef<THREE.Points>(null)
    const usagiRef = useRef<THREE.Mesh>(null)
    const [currentPhase, setCurrentPhase] = useState(AnimationPhase.FORMING_TREE)
    const [phaseProgress, setPhaseProgress] = useState(0)
    const [totalTime, setTotalTime] = useState(0)
    const [fireworks, setFireworks] = useState<Array<{
        id: number
        position: [number, number, number]
        particles: Array<{
            velocity: [number, number, number]
            color: THREE.Color
        }>
        age: number
    }>>([])

    const particleCount = 5000 // Reduced to prevent center brightness from overlap

    // Load Usagi texture - using correct usagi.png
    const usagiTexture = useLoader(THREE.TextureLoader, usagiImg)
    // Generate all position sets
    const particleData = useMemo(() => {
        // Start positions (scattered for tree formation)
        const start = new Float32Array(particleCount * 3)
        for (let i = 0; i < particleCount; i++) {
            start[i * 3] = (Math.random() - 0.5) * 20
            start[i * 3 + 1] = (Math.random() - 0.5) * 15
            start[i * 3 + 2] = (Math.random() - 0.5) * 8
        }

        // Tree positions - SMOOTH continuous cone (NO LAYERS)
        const tree = new Float32Array(particleCount * 3)
        for (let i = 0; i < particleCount; i++) {
            // Completely smooth random height distribution
            const y = Math.random() * 6

            // Smooth cone taper
            const heightRatio = y / 6
            const maxRadius = 2.8 * (1 - heightRatio * 0.88)

            // Random radius within cone
            const radius = Math.random() * maxRadius
            const angle = Math.random() * Math.PI * 2

            tree[i * 3] = Math.cos(angle) * radius
            tree[i * 3 + 1] = y - 3.5  // Moved up from -4.5
            tree[i * 3 + 2] = Math.sin(angle) * radius
        }

        // Dispersed positions - tighter spread for better visibility in FINISHED phase
        const dispersed = new Float32Array(particleCount * 3)
        for (let i = 0; i < particleCount; i++) {
            dispersed[i * 3] = (Math.random() - 0.5) * 20      // Reduced from 30
            dispersed[i * 3 + 1] = (Math.random() - 0.5) * 15  // Reduced from 20
            dispersed[i * 3 + 2] = (Math.random() - 0.5) * 10  // Reduced from 15
        }

        // Colors - vibrant Christmas lights palette like Sydney tree
        const colors = new Float32Array(particleCount * 3)
        const colorPalette = [
            new THREE.Color('#FF0000'), // Bright Red
            new THREE.Color('#00FF00'), // Bright Green  
            new THREE.Color('#0000FF'), // Bright Blue
            new THREE.Color('#FFFF00'), // Bright Yellow
            new THREE.Color('#FF00FF'), // Bright Magenta
            new THREE.Color('#00FFFF'), // Bright Cyan
            new THREE.Color('#FF8800'), // Bright Orange
            new THREE.Color('#FFFFFF'), // White
            new THREE.Color('#FFD700'), // Gold
            new THREE.Color('#FF1493'), // Deep Pink
        ]

        for (let i = 0; i < particleCount; i++) {
            const color = colorPalette[Math.floor(Math.random() * colorPalette.length)]
            colors[i * 3] = color.r
            colors[i * 3 + 1] = color.g
            colors[i * 3 + 2] = color.b
        }

        return { start, tree, dispersed, colors }
    }, [])

    const [currentPositions] = useState(() => new Float32Array(particleData.start))

    // Animation loop
    useFrame((_state, delta) => {
        if (!pointsRef.current) return

        // Don't animate if not active
        if (!isActive) return

        const newTotalTime = totalTime + delta
        setTotalTime(newTotalTime)

        // Phase progression logic (skip for FINISHED)
        if (currentPhase !== AnimationPhase.FINISHED) {
            let phaseDuration = PHASE_DURATIONS[currentPhase]
            let newProgress = phaseProgress + delta / phaseDuration

            if (newProgress >= 1) {
                const nextPhase = currentPhase + 1
                console.log(`Phase transition: ${currentPhase} -> ${nextPhase}`)

                // Move to next phase, but stop at FINISHED
                if (nextPhase <= AnimationPhase.FINISHED) {
                    setCurrentPhase(nextPhase)
                    setPhaseProgress(0)
                    console.log(`Set phase to ${nextPhase}, progress to 0`)
                } else {
                    console.log(`ERROR: nextPhase ${nextPhase} > FINISHED, staying at ${currentPhase}`)
                }
            } else {
                setPhaseProgress(newProgress)
            }
        }

        const positions = pointsRef.current.geometry.attributes.position.array as Float32Array
        const t = easeInOutCubic(currentPhase === AnimationPhase.FINISHED ? 1 : phaseProgress)

        switch (currentPhase) {
            case AnimationPhase.FORMING_TREE:
                for (let i = 0; i < particleCount; i++) {
                    const angle = newTotalTime * 0.5 + i * 0.01
                    const rotationFactor = Math.sin(t * Math.PI)

                    positions[i * 3] =
                        particleData.start[i * 3] * (1 - t) +
                        (particleData.tree[i * 3] * Math.cos(angle * rotationFactor) -
                            particleData.tree[i * 3 + 2] * Math.sin(angle * rotationFactor)) * t
                    positions[i * 3 + 1] =
                        particleData.start[i * 3 + 1] * (1 - t) +
                        particleData.tree[i * 3 + 1] * t
                    positions[i * 3 + 2] =
                        particleData.start[i * 3 + 2] * (1 - t) +
                        (particleData.tree[i * 3] * Math.sin(angle * rotationFactor) +
                            particleData.tree[i * 3 + 2] * Math.cos(angle * rotationFactor)) * t
                }
                break

            case AnimationPhase.TREE_DISPLAY:
                for (let i = 0; i < particleCount; i++) {
                    positions[i * 3] = particleData.tree[i * 3]
                    positions[i * 3 + 1] = particleData.tree[i * 3 + 1]
                    positions[i * 3 + 2] = particleData.tree[i * 3 + 2]
                }
                break

            case AnimationPhase.FORMING_TEXT:
                // Particles disperse and fade out
                for (let i = 0; i < particleCount; i++) {
                    positions[i * 3] = particleData.tree[i * 3] * (1 - t) + particleData.dispersed[i * 3] * t
                    positions[i * 3 + 1] = particleData.tree[i * 3 + 1] * (1 - t) + particleData.dispersed[i * 3 + 1] * t
                    positions[i * 3 + 2] = particleData.tree[i * 3 + 2] * (1 - t) + particleData.dispersed[i * 3 + 2] * t
                }
                break

            case AnimationPhase.TEXT_DISPLAY:
                // Particles completely dispersed and invisible during text
                for (let i = 0; i < particleCount; i++) {
                    positions[i * 3] = particleData.dispersed[i * 3]
                    positions[i * 3 + 1] = particleData.dispersed[i * 3 + 1]
                    positions[i * 3 + 2] = particleData.dispersed[i * 3 + 2]
                }
                break

            case AnimationPhase.FINISHED:
                // Colorful scattered particles in background for text - MORE VISIBLE
                for (let i = 0; i < particleCount; i++) {
                    // Gentle floating motion
                    const floatX = Math.sin(newTotalTime * 0.3 + i * 0.1) * 0.3
                    const floatY = Math.cos(newTotalTime * 0.2 + i * 0.15) * 0.3
                    positions[i * 3] = particleData.dispersed[i * 3] + floatX
                    positions[i * 3 + 1] = particleData.dispersed[i * 3 + 1] + floatY
                    positions[i * 3 + 2] = particleData.dispersed[i * 3 + 2]
                }
                break
        }

        pointsRef.current.geometry.attributes.position.needsUpdate = true

        // No glow layer - removed for clear particle colors

        // Usagi visibility and animation - positioned at tree top
        if (usagiRef.current) {
            if (currentPhase === AnimationPhase.FORMING_TREE || currentPhase === AnimationPhase.TREE_DISPLAY) {
                const usagiOpacity = currentPhase === AnimationPhase.FORMING_TREE ? t : 1
                usagiRef.current.visible = usagiOpacity > 0.1
                usagiRef.current.scale.setScalar(usagiOpacity * 1.0)
                usagiRef.current.rotation.y = newTotalTime * 1.5
                // Cute bouncing - adjusted position
                usagiRef.current.position.y = 3.0 + Math.sin(newTotalTime * 3) * 0.15
            } else {
                usagiRef.current.visible = false
            }
        }

        // Text position animation (no longer managing visibility)
        if (textRef.current) {
            if (currentPhase === AnimationPhase.TEXT_DISPLAY) {
                // Keep static (no floating to prevent jitter)
                textRef.current.position.y = 0

                // Trigger fireworks at specific times during TEXT_DISPLAY
                const textDisplayTime = phaseProgress * PHASE_DURATIONS[AnimationPhase.TEXT_DISPLAY]
                const fireworkTimes = [1, 2.5, 4, 5.5] // 4 fireworks

                fireworkTimes.forEach((time, index) => {
                    if (textDisplayTime >= time && textDisplayTime < time + 0.1) {
                        // Check if this firework hasn't been created yet
                        if (!fireworks.some(fw => fw.id === index)) {
                            const newFirework = {
                                id: index,
                                position: [
                                    (Math.random() - 0.5) * 4,
                                    (Math.random() - 0.5) * 2,
                                    0
                                ] as [number, number, number],
                                particles: Array.from({ length: 50 }, () => ({
                                    velocity: [
                                        (Math.random() - 0.5) * 3,
                                        (Math.random() - 0.5) * 3,
                                        (Math.random() - 0.5) * 3
                                    ] as [number, number, number],
                                    color: new THREE.Color(
                                        ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#FF00FF', '#00FFFF', '#FFFFFF'][Math.floor(Math.random() * 7)]
                                    )
                                })),
                                age: 0
                            }
                            setFireworks(prev => [...prev, newFirework])
                        }
                    }
                })
            } else if (currentPhase === AnimationPhase.FINISHED) {
                // Keep text static in FINISHED phase
                textRef.current.position.y = 0
            } else if (currentPhase === AnimationPhase.FORMING_TEXT) {
                textRef.current.scale.setScalar(t)
                textRef.current.position.y = 0
            }
        }

        // Update fireworks
        setFireworks(prev => prev.map(fw => ({
            ...fw,
            age: fw.age + delta
        })).filter(fw => fw.age < 2)) // Remove old fireworks after 2 seconds
    })

    return (
        <group>
            {/* Main particles */}
            <Points
                ref={pointsRef}
                positions={currentPositions}
                colors={particleData.colors}
                stride={3}
            >
                <PointMaterial
                    transparent
                    vertexColors
                    size={0.08}
                    sizeAttenuation={true}
                    depthWrite={false}
                    blending={THREE.NormalBlending}
                    opacity={0.6}
                />
            </Points>

            {/* Glow layer */}
            <Points
                ref={glowPointsRef}
                positions={currentPositions}
                colors={particleData.colors}
                stride={3}
            >
                <PointMaterial
                    transparent
                    vertexColors
                    size={0.2}
                    sizeAttenuation={true}
                    depthWrite={false}
                    blending={THREE.AdditiveBlending}
                    opacity={0.3}
                />
            </Points>

            {/* Usagi on tree top - positioned at tree top (moved up) */}
            <mesh ref={usagiRef} position={[0, 3.0, 0]} visible={false}>
                <planeGeometry args={[1.5, 1.5]} />
                <meshBasicMaterial
                    map={usagiTexture}
                    transparent
                    alphaTest={0.5}
                    side={THREE.DoubleSide}
                />
            </mesh>

            {/* Usagi glow */}
            {(currentPhase === AnimationPhase.TREE_DISPLAY || currentPhase === AnimationPhase.FORMING_TREE) && (
                <pointLight
                    position={[0, 3.0, 0]}
                    intensity={2}
                    distance={4}
                    color="#FFFFFF"
                />
            )}

            {/* Text: 🎅 Merry Christmas 🎄 - Yellow extra bold text */}
            {(currentPhase === AnimationPhase.FORMING_TEXT ||
                currentPhase === AnimationPhase.TEXT_DISPLAY ||
                currentPhase === AnimationPhase.FINISHED) && (
                    <Text
                        ref={textRef}
                        fontSize={1.2}
                        fontWeight={900}
                        color="#FFD700"
                        anchorX="center"
                        anchorY="middle"
                        outlineWidth={0.04}
                        outlineColor="#000000"
                        letterSpacing={0.05}
                    >
                        🎅 Merry Christmas 🎄
                    </Text>
                )}

            {/* Text glow */}
            {(currentPhase === AnimationPhase.TEXT_DISPLAY || currentPhase === AnimationPhase.FINISHED) && (
                <pointLight
                    position={[0, 0, 2]}
                    intensity={2}
                    distance={10}
                    color="#FFD700"
                />
            )}
        </group>
    )
}
