import { Canvas } from '@react-three/fiber'
import { EffectComposer, Bloom } from '@react-three/postprocessing'
import ParticleAnimation from './ParticleAnimation'

interface SceneProps {
    isActive: boolean
    onAnimationComplete?: () => void
}

export default function Scene({ isActive, onAnimationComplete }: SceneProps) {
    return (
        <Canvas
            camera={{
                position: [0, 0, 12],
                fov: 50,
                near: 0.1,
                far: 1000
            }}
            gl={{
                antialias: true,
                alpha: false,
                powerPreference: 'high-performance'
            }}
        >
            {/* Pure black background */}
            <color attach="background" args={['#000000']} />

            {/* Basic lighting */}
            <ambientLight intensity={0.5} />

            {/* Particle Animation - always rendered, controlled by isActive */}
            <ParticleAnimation isActive={isActive} onAnimationComplete={onAnimationComplete} />

            {/* Post-processing Effects - Bloom disabled for clear colors */}
            <EffectComposer>
                <Bloom
                    intensity={0}
                    luminanceThreshold={1.0}
                    luminanceSmoothing={0.9}
                    radius={1}
                />
            </EffectComposer>
        </Canvas>
    )
}
